import{_ as t,o as i,c as a,ae as o}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"ADR 003: AI Integration & Resilience Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-ai-integration.md","filePath":"adr/003-ai-integration.md"}'),n={name:"adr/003-ai-integration.md"};function r(s,e,c,l,d,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-003-ai-integration-resilience-strategy" tabindex="-1">ADR 003: AI Integration &amp; Resilience Strategy <a class="header-anchor" href="#adr-003-ai-integration-resilience-strategy" aria-label="Permalink to &quot;ADR 003: AI Integration &amp; Resilience Strategy&quot;">​</a></h1><ul><li>Status: superseded by <a href="./012-cloud-pivot-render-turso.html">ADR 012</a></li><li>Deciders: Elena, Senior Architect</li><li>Date: 2026-03-04</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>We need to extract structured technical requirements from unstructured PDF text. Direct regex matching showed limitations (false positives/negatives). However, calling an LLM API (OpenAI) introduces latency, cost, and potential failure points (rate limits, quota exhaustion).</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><strong>Accuracy</strong>: Need semantic understanding of requirements (Mandatory vs Optional).</li><li><strong>Resilience</strong>: The system must not crash if the AI API is down or quota is exceeded.</li><li><strong>Developer Experience</strong>: Developers without paid API keys must be able to work on the project.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>&quot;Hybrid Approach: OpenAI (GPT-4o) + Dictionary-based Mock Fallback&quot;</strong>.</p><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><ol><li><strong>Primary Interface</strong>: <code>ITenderAnalyzer</code> (Clean Architecture).</li><li><strong>Implementation</strong>: <code>OpenAIModelService</code>.</li><li><strong>Mechanism</strong>: <ul><li>Attempt call to OpenAI API using <code>gpt-4o-2024-08-06</code> with <strong>Structured Outputs</strong> (Zod Schema).</li><li>Catch specific errors (<code>429 Rate Limit</code>, <code>401 Unauthorized</code>, <code>insufficient_quota</code>).</li><li>If error is detected, transparently switch to <code>getMockAnalysis()</code> which returns a hardcoded, valid <code>TenderAnalysis</code> object.</li></ul></li></ol><h3 id="justification" tabindex="-1">Justification <a class="header-anchor" href="#justification" aria-label="Permalink to &quot;Justification&quot;">​</a></h3><ul><li><strong>Robustness</strong>: Ensures the application remains functional for testing and demo purposes even without live AI.</li><li><strong>Structure</strong>: Using OpenAI&#39;s JSON mode guarantees the backend logic never receives malformed data.</li><li><strong>Cost Efficiency</strong>: Prevents accidental wallet drain during development loops using the Mock mode.</li></ul><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li>Zero-config start for new developers (Mock mode works out of the box).</li><li>High semantic accuracy when API is available.</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li>Mock data is static and does not reflect the actual uploaded PDF content in fallback mode.</li></ul>',16)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
